{
  "name": "Thorlabs APT压电惯性致动器控制器",
  "name_en": "Thorlabs APT Piezo Inertia Actuator Controller",
  "manufacturer": "Thorlabs",
  "description": "用于驱动和控制 Thorlabs 压电惯性致动器的多通道控制器，典型对应 KIM101 等设备。它可对单轴或多轴执行器进行使能、步进移动、绝对定位及驱动参数设置，常用于光学元件、镜架或精密位移机构的微步进定位与对准实验。",
  "description_en": "A multi-channel controller for Thorlabs piezo inertia actuators, typically including devices such as the KIM101. It enables single- or multi-axis actuators, supports step motion, absolute positioning, and drive parameter configuration, and is commonly used for fine positioning and alignment of optics, mirror mounts, and precision translation mechanisms in laboratory setups.",
  "tag_hints": [
    "piezo inertia actuation",
    "Thorlabs APT",
    "KIM101 controller",
    "multi-axis positioning",
    "stick-slip motion",
    "optical alignment",
    "precision micropositioning"
  ],
  "actions": [
    {
      "action_name": "auto-enabled_multi",
      "description": "获取/设置/定义多通道使能模式",
      "description_en": "Get/set/define the multi-channel enable mode."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号",
      "description_en": "Get the serial number."
    },
    {
      "action_name": "auto-model_number",
      "description": "获取型号",
      "description_en": "Get the model number."
    },
    {
