      "description": "获取通道数量",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "auto-identify",
      "description": "识别设备",
      "description_en": "Identify the device."
    },
    {
      "action_name": "auto-destination",
      "description": "获取/设置/定义目标地址",
      "description_en": "Get/set/define the destination address."
    },
    {
      "action_name": "auto-led_intensity",
      "description": "获取/设置/定义指示灯亮度",
      "description_en": "Get/set/define the LED intensity."
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置/定义使能状态",
      "description_en": "Get/set/define the enabled state."
    },
    {
      "action_name": "auto-max_travel",
      "description": "获取/设置/定义最大行程",
      "description_en": "Get/set/define the maximum travel."
    },
    {
      "action_name": "auto-drive_op_parameters",
      "description": "获取/设置/定义驱动运行参数",
      "description_en": "Get/set/define the drive operating parameters."
    },
    {
      "action_name": "auto-enabled_single",
      "description": "获取/设置/定义单通道使能状态",
      "description_en": "Get/set/define the single-channel enable state."
    },
    {
      "action_name": "auto-jog_parameters",
      "description": "获取/设置/定义点动参数",
      "description_en": "Get/set/define the jog parameters."
    },
    {
      "action_name": "auto-position_count",
      "description": "获取/设置/定义位置计数",
      "description_en": "Get/set/define the position count."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到绝对位置",
      "description_en": "Move to an absolute position."
    },
    {
      "action_name": "auto-move_jog",
      "description": "执行点动移动",
      "description_en": "Perform a jog move."
    },
    {
      "action_name": "auto-move_jog_stop",
      "description": "停止点动移动",
      "description_en": "Stop jog motion."
    },
    {
      "action_name": "auto-position_control_closed",
      "description": "获取/设置/定义闭环位置控制状态",
      "description_en": "Get/set/define the closed-loop position control state."
    },
    {
      "action_name": "auto-change_position_control_mode",
      "description": "切换位置控制模式",
      "description_en": "Change the position control mode."
    },
    {
      "action_name": "auto-output_position",
      "description": "获取/设置/定义输出位置",
      "description_en": "Get/set/define the output position."
    },
    {
      "action_name": "auto-motion_timeout",
      "description": "获取/设置/定义运动超时时间",
      "description_en": "Get/set/define the motion timeout."
    },
    {
      "action_name": "auto-set_scale",
      "description": "定义位置刻度参数",
      "description_en": "Define the position scaling parameters."
    },
    {
      "action_name": "auto-motor_model",
      "description": "获取/设置/定义连接的执行器型号",
      "description_en": "Get/set/define the connected actuator model."
    },
    {
      "action_name": "auto-backlash_correction",
      "description": "获取/设置/定义回程补偿",
      "description_en": "Get/set/define the backlash correction."
    },
    {
      "action_name": "auto-home_parameters",
      "description": "获取/设置/定义回零参数",
      "description_en": "Get/set/define the homing parameters."
    },
    {
      "action_name": "auto-status_bits",
      "description": "获取状态位",
      "description_en": "Get the status bits."
    },
    {
      "action_name": "auto-position",
      "description": "获取/设置/定义位置",
      "description_en": "Get/set/define the position."
    },
    {
      "action_name": "auto-position_encoder",
      "description": "获取编码器位置",
      "description_en": "Get the encoder position."
    },
    {
      "action_name": "auto-go_home",
      "description": "回到原点位置",
      "description_en": "Move to the home position."
    },
    {
      "action_name": "auto-move",
      "description": "移动到目标位置",
      "description_en": "Move to a target position."
    }
  ]
}

